package main

import (
	"fmt"
	"sync"
)

type DB struct{ id int }

var (
	once sync.Once
	db   *DB
)

func instance() *DB {
	once.Do(func() {
		fmt.Println("opening DB (runs once)") // side effect proves single init
		db = &DB{id: 42}
	})
	return db
}

func main() {
	var wg sync.WaitGroup
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_ = instance() // all three race here
		}()
	}
	wg.Wait()
	fmt.Println("db id =", instance().id)
}

