type Service struct {
	once sync.Once
}

func (s *Service) Setup() { // pointer receiver: same Once every call
	s.once.Do(func() {
		fmt.Println("init")
	})
}

func main() {
	svc := &Service{}
	svc.Setup()
	svc.Setup() // no-op now
}

import "sync"

type Once[T any] struct {
	once sync.Once
	val  T
}

// Do runs f exactly once across all goroutines and caches the result.
func (o *Once[T]) Do(f func() T) T {
	o.once.Do(func() {
		o.val = f() // computed on the first call only
	})
	return o.val // once.Do publishes o.val to all callers
}
